var n={en:`The API bypasses tenant and role checks and admin UI accesses the shared database directly. A manager from Tenant A can read Tenant B data.`,ua:`API обходить перевірку тенанта й ролей, а адмінський UI напряму читає спільну базу. Менеджер тенанта A бачить дані тенанта B.`};var t={en:[`Remove api→domain bypass and admin→db direct access.`,`Restore api→tenant and api→roles routes.`,`Specify denial tests for missing and forged tenant context.`],ua:[`Прибери обхід api→domain та прямий admin→db.`,`Віднови api→tenant і api→roles.`,`Визнач тести відмови при відсутньому або підробленому тенанті.`]};var d=[{en:`Protected domain access includes verified tenant and permission checks.`,ua:`Захищений доступ перевіряє тенанта й дозволи.`},{en:`There is no direct client-to-storage edge.`,ua:`Немає прямого шляху від клієнта до сховища.`}];var i={remove:[`api->tenant`,`api->roles`],add:[{from:`api`,to:`domain`,kind:`sync`,label:`Intentional defect / Навмисна помилка`},{from:`admin`,to:`db`,kind:`data`,label:`Intentional defect / Навмисна помилка`}]};var s={scenario:n,tasks:t,checks:d,mutations:i};export{d as checks,s as default,i as mutations,n as scenario,t as tasks};